select id, service, host, log_ts, level, latency_ms, payload_json, get_json_object(payload_json, '$.user.tier') as user_tier, context['region'] as region, coalesce(context['version'], 'direct') as version_or_default, coalesce(context['trace'], 'direct') as trace_or_default, from_json(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').user.tier as tier from app_logs
